# access_control.py
from datetime import datetime
from functools import wraps
import json

class AccessDenied(Exception):
    """Raised when access is denied"""
    pass

def check_ip_whitelist(allowed_ips):
    """Decorator to restrict access by IP address"""
    def decorator(func):
        @wraps(func)
        def wrapper(request, *args, **kwargs):
            client_ip = request.get('client_ip')
            if client_ip not in allowed_ips:
                raise AccessDenied(f"IP {client_ip} not whitelisted")
            return func(request, *args, **kwargs)
        return wrapper
    return decorator

def check_authentication(func):
    """Decorator to require valid authentication"""
    @wraps(func)
    def wrapper(request, *args, **kwargs):
        if not request.get('auth_token'):
            raise AccessDenied("Authentication required")
        if not validate_token(request['auth_token']):
            raise AccessDenied("Invalid authentication token")
        return func(request, *args, **kwargs)
    return wrapper

def check_rate_limit(max_requests=100, window_seconds=3600):
    """Decorator to enforce rate limiting"""
    request_log = {}

    def decorator(func):
        @wraps(func)
        def wrapper(request, *args, **kwargs):
            user_id = request.get('user_id')
            now = datetime.now().timestamp()

            if user_id not in request_log:
                request_log[user_id] = []

            # Remove old requests outside window
            request_log[user_id] = [
                ts for ts in request_log[user_id] 
                if now - ts < window_seconds
            ]

            if len(request_log[user_id]) >= max_requests:
                raise AccessDenied(
                    f"Rate limit exceeded: {max_requests} requests per hour"
                )

            request_log[user_id].append(now)
            return func(request, *args, **kwargs)
        return wrapper
    return decorator

def validate_token(token):
    """Validate authentication token"""
    # Simplified validation
    return token and len(token) > 10

